from collections import Counter, defaultdict

def components(g, bg):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                col=g[i][j]; st=[(i,j)]; comp=[]; seen.add((i,j))
                while st:
                    y,x=st.pop(); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and g[ny][nx]==col:
                                seen.add((ny,nx)); st.append((ny,nx))
                out.append((col,comp))
    return out

def sil(comp):
    ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
    return tuple(sorted((y-min(ys),x-min(xs)) for y,x in comp))

def centroid(comp):
    return (sum(p[0] for p in comp)/len(comp), sum(p[1] for p in comp)/len(comp))

def transform(g):
    H,W=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row)
    bg=cnt.most_common(1)[0][0]
    comps=components(g,bg)
    silcount=Counter(sil(c) for _,c in comps)
    # template: color appearing once, silhouette unique
    tmpl=None
    for col,c in comps:
        if sum(1 for col2,_ in comps if col2==col)==1 and silcount[sil(c)]==1:
            tmpl=(col,c)
    tcol, tcomp = tmpl
    tc=centroid(tcomp)
    # duplicate silhouette groups among non-template shapes
    groups=defaultdict(list)
    for col,c in comps:
        if (col,c)==tmpl: continue
        if silcount[sil(c)]>1: groups[sil(c)].append((col,c))
    if not groups: return [row[:] for row in g]
    # group with largest member size
    best=max(groups.values(), key=lambda l: len(l[0][1]))
    # recolor member farthest from template centroid
    far=max(best, key=lambda cc: math.dist(centroid(cc[1]), tc))
    out=[row[:] for row in g]
    for y,x in far[1]: out[y][x]=tcol
    return out

