import numpy as np, math
def comps_of(g, bg, conn=8):
    R,C=len(g),len(g[0]); seen=[[False]*C for _ in range(R)]; out=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]!=bg and not seen[r][c]:
                col=g[r][c]; st=[(r,c)]; seen[r][c]=True; cells=[]
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy in range(-1,2):
                        for dx in range(-1,2):
                            if dy==0 and dx==0: continue
                            if conn==4 and abs(dy)+abs(dx)!=1: continue
                            ny,nx=y+dy,x+dx
                            if 0<=ny<R and 0<=nx<C and not seen[ny][nx] and g[ny][nx]!=bg:
                                seen[ny][nx]=True; st.append((ny,nx))
                out.append((col,cells))
    return out
def analyze(din, dout, name):
    R,C=len(din),len(din[0])
    cnt=Counter(v for row in din for v in row)
    bg=cnt.most_common(1)[0][0]
    comps=comps_of(din,bg,8)
    diff=[(r,c,din[r][c],dout[r][c]) for r in range(R) for c in range(C) if din[r][c]!=dout[r][c]]
    # unique color comp = template
    tmpl=[(col,cells) for col,cells in comps if cnt[col]==1][0]
    print(f'--- {name}: {R}x{C} bg={bg} ncomps={len(comps)} diff={diff}')
    print('  template color',tmpl[0],'cells',sorted(tmpl[1]))
    for col,cells in sorted(comps,key=lambda x:-len(x[1])):
        if cells==tmpl[1]: continue
        print('  comp col',col,'size',len(cells),'bbox',(min(r for r,c in cells),min(c for r,c in cells),max(r for r,c in cells),max(c for r,c in cells)),sorted(cells))
